import {WebSocket} from 'ws';
import {startEngineWith, connectClient, cleanup, delegatingTo} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {ErrorCodes} from '../types/session.js';

describe('history opt-in', () => {
  const clients: WebSocket[] = [];
  const servers: any[] = [];

  afterEach(async () => {
    await cleanup(clients, servers);
  });

  it('answers UNSUPPORTED when history is not enabled', async () => {
    const store = new InMemorySessionStore();
    const {url, hal} = await startEngineWith({
      sessionStore: delegatingTo(store),
      // history is missing from HalServerOptions currently
    });
    servers.push(hal);

    const client = connectClient(url);
    const frame = await new Promise<any>(resolve => {
      client.on('message', raw => {
        const f = JSON.parse(String(raw));
        if (f.type === 'connected') {
          client.send(JSON.stringify({type: 'list_sessions'}));
        } else if (f.type !== 'pong') {
          resolve(f);
        }
      });
    });

    expect(frame).toEqual({
      type: 'error',
      code: 'UNSUPPORTED',
      message: expect.any(String),
    });
  });
});

