async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  store: SessionStore | undefined,
  history: {enabled: boolean} | undefined,
  limit?: number,
  before?: {updatedAt: string | number; sessionId: string}
): Promise<void> {
  if (!history?.enabled || !store?.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not supported');
    return;
  }
  try {
    const summaries = await store.listFor(session.userId, {limit, before});
    const sessions = summaries.map(s => ({
      ...s,
      createdAt: s.createdAt.toISOString(),
      updatedAt: s.updatedAt.toISOString(),
    }));
    sendSessionList(ws, sessions);
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not supported by the store');
      return;
    }
    log.error('ws', 'listFor failed', {userId: session.userId, error: messageOf(error)});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list sessions');
  }
}

